BEGIN;
CREATE TYPE user_role AS ENUM ('admin','staff');
CREATE TYPE payment_method AS ENUM ('cash','card','upi');
CREATE TYPE payment_status AS ENUM ('paid','voided','refunded');
CREATE TYPE po_status AS ENUM ('draft','sent','partially_received','received','cancelled');
CREATE TYPE customer_segment AS ENUM ('new','regular','at_risk','vip');

CREATE TABLE stores (store_id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, location TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (user_id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role user_role NOT NULL, store_id BIGINT REFERENCES stores(store_id), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (role = 'admin' OR store_id IS NOT NULL));
CREATE TABLE customers (customer_id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(30) UNIQUE, email VARCHAR(255), loyalty_points INTEGER NOT NULL DEFAULT 0 CHECK (loyalty_points >= 0), segment customer_segment NOT NULL DEFAULT 'new', last_purchase_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE categories (category_id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE suppliers (supplier_id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(255), phone VARCHAR(30), address TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products (product_id BIGSERIAL PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES categories(category_id), supplier_id BIGINT REFERENCES suppliers(supplier_id), sku VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, description TEXT, price NUMERIC(12,2) NOT NULL CHECK (price > 0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inventory (inventory_id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(product_id) ON DELETE RESTRICT, store_id BIGINT NOT NULL REFERENCES stores(store_id) ON DELETE RESTRICT, quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0), reorder_threshold INTEGER NOT NULL DEFAULT 5 CHECK (reorder_threshold >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(product_id, store_id));
CREATE TABLE orders (order_id BIGSERIAL PRIMARY KEY, receipt_number VARCHAR(40) NOT NULL UNIQUE, customer_id BIGINT REFERENCES customers(customer_id), store_id BIGINT NOT NULL REFERENCES stores(store_id), staff_user_id BIGINT NOT NULL REFERENCES users(user_id), subtotal NUMERIC(12,2) NOT NULL CHECK (subtotal >= 0), discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0), tax_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0), total_amount NUMERIC(12,2) NOT NULL CHECK (total_amount >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (order_item_id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(product_id) ON DELETE RESTRICT, quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price > 0), line_total NUMERIC(12,2) NOT NULL CHECK (line_total >= 0));
CREATE TABLE payments (payment_id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(order_id), amount NUMERIC(12,2) NOT NULL CHECK (amount > 0), method payment_method NOT NULL, status payment_status NOT NULL DEFAULT 'paid', paid_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE purchase_orders (po_id BIGSERIAL PRIMARY KEY, supplier_id BIGINT NOT NULL REFERENCES suppliers(supplier_id), store_id BIGINT NOT NULL REFERENCES stores(store_id), created_by BIGINT NOT NULL REFERENCES users(user_id), status po_status NOT NULL DEFAULT 'draft', expected_at DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE purchase_order_items (po_item_id BIGSERIAL PRIMARY KEY, po_id BIGINT NOT NULL REFERENCES purchase_orders(po_id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(product_id), ordered_qty INTEGER NOT NULL CHECK (ordered_qty > 0), received_qty INTEGER NOT NULL DEFAULT 0 CHECK (received_qty >= 0 AND received_qty <= ordered_qty), unit_cost NUMERIC(12,2) CHECK (unit_cost > 0), UNIQUE(po_id, product_id));
CREATE TABLE stock_movements (movement_id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(product_id), store_id BIGINT NOT NULL REFERENCES stores(store_id), change_qty INTEGER NOT NULL CHECK (change_qty <> 0), reason VARCHAR(80) NOT NULL, reference_type VARCHAR(40), reference_id BIGINT, actor_user_id BIGINT NOT NULL REFERENCES users(user_id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE loyalty_ledger (entry_id BIGSERIAL PRIMARY KEY, customer_id BIGINT NOT NULL REFERENCES customers(customer_id), order_id BIGINT REFERENCES orders(order_id), points_delta INTEGER NOT NULL CHECK (points_delta <> 0), reason VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
COMMIT;
